# %% [markdown]
# ## Step 2 — Define Tool Registry & Implementations
#
# We'll build the same multi-tool agent from the lesson: weather lookup, calculator, web search, file reading, and code execution. Each tool has a JSON Schema definition (what the model sees) and a Python function (what your code executes).

# %%
import math, time

# In-memory tool definitions and implementations
TOOL_REGISTRY = {}

def register_tool(name, description, parameters, function):
    TOOL_REGISTRY[name] = {
        "definition": {
            "type": "function",
            "function": {"name": name, "description": description, "parameters": parameters},
        },
        "function": function,
    }

# Weather database
WEATHER_DB = {
    "tokyo": {"temp_c": 18, "condition": "cloudy", "humidity": 72, "wind_kph": 14},
    "new york": {"temp_c": 22, "condition": "sunny", "humidity": 45, "wind_kph": 8},
    "london": {"temp_c": 12, "condition": "rainy", "humidity": 88, "wind_kph": 22},
}

def get_weather(city, units="celsius"):
    key = city.lower().strip()
    if key not in WEATHER_DB:
        return {"error": True, "message": f"City '{city}' not found.", "code": "CITY_NOT_FOUND"}
    data = WEATHER_DB[key].copy()
    if units == "fahrenheit":
        data["temp_f"] = round(data["temp_c"] * 9 / 5 + 32, 1)
        del data["temp_c"]
    data["city"] = city
    return data

def calculator(expression, precision=2):
    allowed = set("0123456789+-*/.() ")
    if not all(c in allowed for c in expression):
        return {"error": True, "message": f"Invalid characters in expression"}
    try:
        result = eval(expression, {"__builtins__": {}}, {"math": math})
        return {"result": round(float(result), precision), "expression": expression}
    except Exception as e:
        return {"error": True, "message": str(e)}

# Register the tools
register_tool(
    "get_weather",
    "Get current weather for a city. Returns temperature, condition, humidity, and wind speed.",
    {"type": "object", "properties": {"city": {"type": "string", "description": "City name, e.g. 'Tokyo' or 'London'"}, "units": {"type": "string", "enum": ["celsius", "fahrenheit"], "description": "Temperature units"}}, "required": ["city"]},
    get_weather,
)
register_tool(
    "calculator",
    "Evaluate a mathematical expression. Supports +, -, *, /, parentheses, and decimals. Returns the numeric result.",
    {"type": "object", "properties": {"expression": {"type": "string", "description": "Math expression, e.g. '(10 + 5) * 3'"}, "precision": {"type": "integer", "description": "Decimal places in result"}}, "required": ["expression"]},
    calculator,
)

print(f"✅ Registered {len(TOOL_REGISTRY)} tools")
for name in TOOL_REGISTRY:
    print(f"  - {name}")

# %% [markdown]
# ## Step 3 — Execute Tool Calls
#
# When the model decides which tool to call, we execute the actual function and return the result.

# %%
def execute_tool_call(tool_call):
    """Execute a tool call and return the result with timing."""
    name = tool_call["name"]
    args = tool_call.get("arguments", {})
    
    if name not in TOOL_REGISTRY:
        return {"error": True, "message": f"Unknown tool: {name}", "code": "UNKNOWN_TOOL"}
    
    func = TOOL_REGISTRY[name]["function"]
    start = time.time()
    
    try:
        result = func(**args)
    except TypeError as e:
        result = {"error": True, "message": f"Invalid arguments: {e}"}
    
    elapsed_ms = round((time.time() - start) * 1000, 2)
    return {"tool": name, "result": result, "execution_time_ms": elapsed_ms}

# Test direct execution
print("Direct tool execution test:")
test_call = {"name": "calculator", "arguments": {"expression": "(10 + 5) * 3 / 2"}}
exec_result = execute_tool_call(test_call)
print(f"Tool: {exec_result['tool']}")
print(f"Result: {exec_result['result']}")
print(f"Time: {exec_result['execution_time_ms']}ms")

# %% [markdown]
# ## Step 4 — The Function Calling Loop: Use Real LLM Calls
#
# This is the core agent loop. We send the user's message and tool definitions to the LLM. The model decides which tool to call. We execute it. The result goes back to the model for synthesis.

# %%
async def run_function_calling_loop(user_message):
    """
    Run a single turn of the function calling loop:
    1. Send user message + tool definitions to LLM
    2. LLM decides which tool to call
    3. Execute the tool
    4. Return result to user
    """
    # Prepare tool definitions for the LLM
    tool_definitions = [t["definition"] for t in TOOL_REGISTRY.values()]
    
    # Step 1: Call LLM to decide which tool(s) to invoke
    system_prompt = """You are a helpful assistant with access to tools.
When the user asks a question:
1. Decide which tool(s) would help answer it
2. Call the appropriate tool with the correct arguments
3. DO NOT call tools for general knowledge questions

You MUST respond with a JSON object in this exact format:
{"tool_name": "<name>", "arguments": {<args>}}

Or if no tool is needed:
{"response": "Your direct answer here"}"""
    
    messages = [{"role": "user", "content": user_message}]
    
    response = await lrn_llm.call(messages, system=system_prompt, max_tokens=300)
    model_output = lrn_llm.text(response)
    
    print(f"LLM decision: {model_output[:150]}..." if len(model_output) > 150 else f"LLM decision: {model_output}")
    
    # Step 2: Parse the LLM's decision
    try:
        decision = json.loads(model_output)
    except json.JSONDecodeError:
        return {"error": True, "message": "LLM returned invalid JSON", "raw": model_output}
    
    # Step 3: If no tool needed, return direct response
    if "response" in decision:
        return {"type": "direct", "response": decision["response"]}
    
    # Step 4: Execute the tool call
    if "tool_name" in decision:
        tool_call = {"name": decision["tool_name"], "arguments": decision.get("arguments", {})}
        exec_result = execute_tool_call(tool_call)
        
        if exec_result["result"].get("error"):
            return {"type": "error", "tool": exec_result["tool"], "error": exec_result["result"]["message"]}
        
        return {"type": "tool_call", "tool": exec_result["tool"], "result": exec_result["result"], "time_ms": exec_result["execution_time_ms"]}
    
    return {"error": True, "message": "LLM response did not contain tool_name or response field"}

print("✅ Function calling loop ready")

